var n=`1325-sopaipillas`;var t=`world-1325`;var a=`CL`;var o=`south-america`;var s=8;var r=63;var l={en:`Sopaipillas`,ua:`Сопайпільяс`};var p={en:`Sopaipillas is a dish from Chile featuring pumpkin, all-purpose flour, baking powder. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Сопайпільяс, страва кухні країни Чилі з такими основними складниками: гарбуз, пшеничне борошно універсальне, розпушувач тіста. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var u=[{en:`Cook the listed ingredients in simmering water for about 25 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 25 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:25,i:[[`pumpkin`,500,`g`],[`water`,700,`ml`]]},{en:`Drain the cooked ingredients and pound or mash while warm for about 9 minutes until thick, elastic and smooth; shape into portions with wet hands or a spoon.`,ua:`Злийте воду з готових продуктів і протягом приблизно 9 хвилин товчіть або розминайте теплими до густої гладкої еластичної маси; сформуйте порції вологими руками чи ложкою.`,t:[`mashing`,`pounding`],m:9,i:[[`all-purpose-flour`,390,`g`],[`baking-powder`,12,`g`],[`table-salt`,6,`g`]]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:11,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 15 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 15 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:15,i:[[`canola-oil`,850,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`powdered-sugar`,75,`g`]]}];var d={slug:n,id:t,country:`CL`,region:o,servings:8,minutes:63,title:l,text:p,steps:u};export{a as country,d as default,t as id,r as minutes,o as region,s as servings,n as slug,u as steps,p as text,l as title};